# ---------------------------------------------------------------- plan geometry
def poly_in(P, x, z):
    c = False; n = len(P)
    for i in range(n):
        (ax, az), (bx, bz) = P[i], P[(i + 1) % n]
        if (az > z) != (bz > z) and x < ax + (bx - ax) * (z - az) / (bz - az): c = not c
    return c
def seg_d(x, z, a, b):
    ex, ez = b[0] - a[0], b[1] - a[1]; L2 = ex * ex + ez * ez or 1e-9; t = max(0, min(1, ((x - a[0]) * ex + (z - a[1]) * ez) / L2))
    return math.hypot(x - a[0] - t * ex, z - a[1] - t * ez)
def poly_d(P, x, z, closed=True):
    n = len(P); return min(seg_d(x, z, P[i], P[(i + 1) % n]) for i in range(n if closed else n - 1))
def near(P, x, z, m): return poly_in(P, x, z) or poly_d(P, x, z) <= m
DG = [[int(v) / 10 for v in row.split()] for row in DTM]; DNX, DNZ = len(DG[0]), len(DG)
def bilin(G, x, z):
    fx = (x - DTM_ORIGIN[0]) / DTM_CELL; fz = (z - DTM_ORIGIN[1]) / DTM_CELL
    i = max(0, min(DNX - 2, int(math.floor(fx)))); j = max(0, min(DNZ - 2, int(math.floor(fz)))); u = fx - i; v = fz - j
    return G[j][i] * (1 - u) * (1 - v) + G[j][i + 1] * u * (1 - v) + G[j + 1][i] * (1 - u) * v + G[j + 1][i + 1] * u * v
def dtm(x, z): return bilin(DG, x, z)
def smooth(t): t = max(0.0, min(1.0, t)); return t * t * (3 - 2 * t)
def vest(z): return VEST * smooth((-z - 5.5) / 6.0)       # the vestibule: level with the street at the pavilions' backs, rising to VEST
def ma(v, n=1): return [sum(v[max(0, i - n):i + n + 1]) / len(v[max(0, i - n):i + n + 1]) for i in range(len(v))]

