YT = [y + n * RISE for y, n in zip(YF, NST)]
STAIR_TOP = ZT[3]
def stair_y(z):
    """the walking level beside the stair at z: up the flights, level on the landings"""
    if z >= ZF[0]: return VEST
    for k in range(4):
        if z >= ZT[k]: return YF[k] + (ZF[k] - z) / (ZF[k] - ZT[k]) * (YT[k] - YF[k])
        if k < 3 and z >= ZF[k + 1]: return YT[k]
    return FLOOR
# the walls' line (x off the axis, z): round the outer edges of the flights and landings, splaying out at the foot
WALL_OFF = [(9.6, -13.6), (7.9, -15.7), (6.4, -17.6), (6.4, ZT[0]), (4.6, ZT[0] - 1.3), (4.6, ZT[2] + 0.6), (7.15, ZT[2] + 0.1), (7.15, STAIR_TOP)]
def dense(P, step=0.5):
    """a polyline with points every `step` along its straight runs (a sweep's smooth curve then keeps to them)"""
    out = [P[0]]
    for a, b in zip(P, P[1:]):
        n = max(1, round(math.dist(a, b) / step)); out += [[r3(a[0] + (b[0] - a[0]) * t / n), r3(a[1] + (b[1] - a[1]) * t / n)] for t in range(1, n + 1)]
    return out

# ---------------------------------------------------------------- the floors: the hall's and the terraces before its open fronts
def offset_line(a, b, d):
    ex, ez = b[0] - a[0], b[1] - a[1]; L = math.hypot(ex, ez); nx, nz = -ez / L, ex / L   # (to the right of a -> b)
    return [a[0] + nx * d, a[1] + nz * d], [b[0] + nx * d, b[1] + nz * d]
def at_z(a, b, z): return [a[0] + (b[0] - a[0]) * (z - a[1]) / (b[1] - a[1]), z]
