# ---------------------------------------------------------------- the porticoes: the washerwoman's, the viaducts
def path_len(P): return [0.0] + [sum(math.dist(P[k], P[k + 1]) for k in range(i)) for i in range(1, len(P))]
def side_h(P, i, d):
    a = P[max(0, i - 1)]; b = P[min(len(P) - 1, i + 1)]; tx, tz = b[0] - a[0], b[1] - a[1]; L = math.hypot(tx, tz)
    rx, rz = -tz / L, tx / L
    return dtm(P[i][0] + rx * d, P[i][1] + rz * d)
PORTICOES = []   # (name, 2-D path, floor ys, width): what the ground is cut for
# the washerwoman's: its floor the ground on its open side (MDT05), smoothed
bug_y = ma([side_h(BUGADERA, i, 5.0) - 0.2 for i in range(len(BUGADERA))], 2)
PORTICOES.append(("bugadera", BUGADERA, bug_y, 4.2))
# the viaducts: the deck straight between the heights where its ends meet the ground; the gallery under it where it
# stands clear of the hill by 2.5 m or more, its wall on the uphill side (the path turned so the hill is on its left)
VIA = {}
for nm, P, Hh, W in (("baix", BAIX, 4.5, 5.0), ("mig", MIG, 5.0, 5.6), ("dalt", DALT, 6.2, 6.0)):
    if sum(side_h(P, i, 5) - side_h(P, i, -5) for i in range(len(P))) > 0: P = P[::-1]
    L = path_len(P); y0, y1 = dtm(*P[0]), dtm(*P[-1])
    deck = [y0 + (y1 - y0) * l / L[-1] for l in L]
    clear = [d - dtm(x, z) for d, (x, z) in zip(deck, P)]
    ks = [i for i, c in enumerate(clear) if c >= 2.5]
    a, b = (ks[0], ks[-1]) if ks else (0, len(P) - 1)
    a = max(0, a - 1); b = min(len(P) - 1, b + 1)
    # (the gallery's floor eased toward the ground at its open edge, within 1.5 m, and the deck with it: so the way under
    #  it is walked in from the hillside, as the paths below the viaducts are)
    fl = [d - Hh for d in deck]
    for k in range(a + 1, b):
        fl[k] = max(deck[k] - Hh - 1.5, min(deck[k] - Hh + 1.5, side_h(P, k, W + 2.0) - 0.1))
    fl = fl[:a + 1] + ma(fl[a + 1:b], 1) + fl[b:] if b - a > 2 else fl
    deck = [f + Hh if a < k < b else d for k, (f, d) in enumerate(zip(fl, deck))]
    VIA[nm] = {"path": P, "deck": deck, "a": a, "b": b, "H": Hh, "W": W, "len": L[-1], "clear": max(clear)}
    PORTICOES.append((nm, P[a:b + 1], [d - Hh for d in deck[a:b + 1]], W))

# ---------------------------------------------------------------- the ground's grid: MDT05 cut for what is built
def in_strip(x, z, P, ys, W):
    """within a portico's gallery (from its wall line across its open side): the floor's height there (or None)"""
    best = None
    for k in range(len(P) - 1):
        a, b = P[k], P[k + 1]; ex, ez = b[0] - a[0], b[1] - a[1]; L = math.hypot(ex, ez)
        t = ((x - a[0]) * ex + (z - a[1]) * ez) / (L * L)
        if t < -0.05 or t > 1.05: continue
        u = ((x - a[0]) * -ez + (z - a[1]) * ex) / L          # (to the right of travel, positive)
        if -2.0 <= u <= W + 3.0:
            y = ys[k] + (ys[k + 1] - ys[k]) * max(0, min(1, t)); best = y if best is None else min(best, y)
    return best
LODGE_BOX = [[4.2, -5.3], [19.9, -5.3], [19.9, 3.1], [4.2, 3.1]]; ADMIN_BOX = [[-18.2, -4.9], [-4.9, -4.9], [-4.9, 2.3], [-18.2, 2.3]]
LARRARD_Y = r3(min(dtm(x, z) for x, z in LARRARD) - 0.4)
MUSEU_Y = r3(min(dtm(x, z) for x, z in MUSEU) - 0.3)
GX0, GZ0 = DTM_ORIGIN; GX1, GZ1 = GX0 + (DNX - 1) * DTM_CELL, GZ0 + (DNZ - 1) * DTM_CELL
def ground_node(x, z):
    h = dtm(x, z)
    # the vestibule, levelled; the stair's cut and the beds beside it no higher than its walls' planters
    if -26 <= x <= 23 and -17.6 <= z <= 1.0: h = vest(z)
    if abs(x - AX) < 15 and -46 < z < -12: h = min(h, stair_y(z + 5) + 1.8)
    if abs(x - AX) < 10.6 and -46 < z < -12: h = min(h, stair_y(z + 5) - 0.3)
    # the hall, its terraces, the square: under their floors (and a cell round them, so no slope stands through a wall)
    if near(FLOORP, x, z, 5.2): h = min(h, FLOOR - 0.4)
    elif poly_in(TERRACE, x, z): h = min(h, PL - 0.5)
    elif near(TERRACE, x, z, 5.2): h = min(h, PL + 0.3)
    # the buildings, on their own floors
    for B, y in ((LODGE_BOX, 0.0), (ADMIN_BOX, 0.0), (COTXERA, 0.5), (LARRARD, LARRARD_Y), (MUSEU, MUSEU_Y)):
        if near(B, x, z, 1.0): h = min(h, y)
    # the porticoes' galleries; the viaducts' causeways under their decks
    for nm, P, ys, W in PORTICOES:
        y = in_strip(x, z, P, ys, W)
        if y is not None: h = min(h, y - 0.25)
    for v in VIA.values():
        for k in list(range(0, v["a"] + 1)) + list(range(v["b"], len(v["path"]))):
            if math.dist(v["path"][k], (x, z)) < v["W"] * 0.5 + 3: h = min(h, v["deck"][k] - 0.3)
    # the edge of the site: the hill let down to the world's level round it (the world is flat outside)
    # (and across the street in front, which climbs 11 m to the west: down to the gate's level at the frame's edge)
    w = smooth(min((x - GX0) / 35.0, (GX1 - x) / 35.0, (z - GZ0) / 60.0, 1.0))
    ws = smooth((GZ1 - z) / 16.0) if z > 6 else 1.0
    return max(0.0, h * w * ws)
GH = [[ground_node(GX0 + i * DTM_CELL, GZ0 + j * DTM_CELL) for i in range(DNX)] for j in range(DNZ)]
def ground(x, z): return bilin(GH, x, z)
def ground_low(x, z):
    """the lowest corner of the terrain's cell at (x, z): under whichever way its two triangles are cut"""
    i = max(0, min(DNX - 2, int((x - GX0) // DTM_CELL))); j = max(0, min(DNZ - 2, int((z - GZ0) // DTM_CELL)))
    return min(GH[j][i], GH[j][i + 1], GH[j + 1][i], GH[j + 1][i + 1])
# ---------------------------------------------------------------- the paths: OSM's footways over the hill, cut into it
# (each run of a way that is clear of what is built, at the ground's height along its line; the ground within 2.5 m of
#  its edges let down to it -- the cut -- and the way laid on top as a bank of rubble 2.2 m deep: on a slope its downhill
#  side stands as a retaining wall)
CALV, CALV_R = (-202.3, -18.8), 3.6       # the Calvary (OSM 6286148116, the peak, 185 m; 11994479654 the cross): in the 15 m ring of way 61942870
def tri_h(G, x, z):
    """the height of the terrain AS TRIANGULATED (each cell split along its shorter diagonal, as arch/assemble.js does)"""
    fx = (x - GX0) / DTM_CELL; fz = (z - GZ0) / DTM_CELL
    i = max(0, min(DNX - 2, int(math.floor(fx)))); j = max(0, min(DNZ - 2, int(math.floor(fz)))); u = fx - i; v = fz - j
    a, b, c, d = G[j][i], G[j][i + 1], G[j + 1][i + 1], G[j + 1][i]
    if abs(a - c) <= abs(b - d): return a + (b - a) * u + (c - b) * v if u >= v else a + (c - d) * u + (d - a) * v
    return a + (b - a) * u + (d - a) * v if u + v <= 1 else c + (d - c) * (1 - u) + (b - c) * (1 - v)
def written(G): return [[-0.2 if h <= 0.05 else round(h * 10) / 10 for h in row] for row in G]
def built_near(x, z, m):
    """within m of something built (the paths keep off it; their cut does not reach it)"""
    if z > -3 or near(FLOORP, x, z, m) or near(TERRACE, x, z, m): return True
    if -27 - m <= x <= 24 + m and -19 - m <= z <= 1 + m: return True
    if abs(x - AX) < 11 + m and -46 < z < -12: return True
    if any(near(B, x, z, m) for B in (LODGE_BOX, ADMIN_BOX, COTXERA, LARRARD, MUSEU)): return True
    if any(poly_d(P, x, z, False) < W + m for nm, P, ys, W in PORTICOES): return True
    for v in VIA.values():                 # (the gallery kept clear; at the ends the paths run up to the causeways' sides)
        P = v["path"]
        if poly_d(P[v["a"]:v["b"] + 1], x, z, False) < v["W"] + m: return True
        if any(len(seg) > 1 and poly_d(seg, x, z, False) < v["W"] * 0.5 + 0.5 * m for seg in (P[:v["a"] + 1], P[v["b"]:])): return True
    return math.dist((x, z), CALV) < CALV_R + 1.0 + m
GW0 = written(GH)
RUNS = []                                  # [way, kind, width, [[x, z]...], [y...]]
for way, kind, w, P in PATHS:
    cur = []
    for q in dense(P, 2.0) + [None]:
        if q is not None and GX0 + 4 < q[0] < GX1 - 4 and GZ0 + 4 < q[1] < GZ1 - 4 and not built_near(q[0], q[1], 1.0): cur.append(q); continue
        if len(cur) >= 3: RUNS.append([way, kind, w, cur, ma([tri_h(GW0, x, z) for x, z in cur], 1)])
        cur = []
PROTECT = [[built_near(GX0 + i * DTM_CELL, GZ0 + j * DTM_CELL, 4.0) for i in range(DNX)] for j in range(DNZ)]
for way, kind, w, P, ys in RUNS:
    rad = w / 2 + 2.5
    for (x, z), y in zip(P, ys):
        for j in range(max(0, int((z - rad - GZ0) // DTM_CELL)), min(DNZ, int((z + rad - GZ0) // DTM_CELL) + 2)):
            for i in range(max(0, int((x - rad - GX0) // DTM_CELL)), min(DNX, int((x + rad - GX0) // DTM_CELL) + 2)):
                if not PROTECT[j][i] and math.hypot(GX0 + i * DTM_CELL - x, GZ0 + j * DTM_CELL - z) < rad: GH[j][i] = min(GH[j][i], max(0.0, y - 0.05))
GW = written(GH)
for r in RUNS:                             # (on the cut ground: never under it, at its middle or its edges)
    way, kind, w, P, ys = r; out = []
    for k, ((x, z), y) in enumerate(zip(P, ys)):
        a, b = P[max(0, k - 1)], P[min(len(P) - 1, k + 1)]; L = math.dist(a, b) or 1.0; nx, nz = -(b[1] - a[1]) / L, (b[0] - a[0]) / L
        out.append(r3(max([y] + [tri_h(GW, x + nx * e, z + nz * e) for e in (-w / 2, 0, w / 2)]) + 0.06))
    r[4] = out
PATH_PTS = {}                              # (a coarse index of the paths' points: the trees keep off them)
for way, kind, w, P, ys in RUNS:
    for x, z in P: PATH_PTS.setdefault((int(x // 10), int(z // 10)), []).append((x, z, w))
def near_path(x, z, m):
    return any(math.hypot(x - px, z - pz) < pw / 2 + m for i in (-1, 0, 1) for j in (-1, 0, 1) for px, pz, pw in PATH_PTS.get((int(x // 10) + i, int(z // 10) + j), ()))
add("hill", {"type": "terrain", "origin": [GX0, GZ0], "cell": DTM_CELL, "scale": 0.1, "base": -0.3, "bottom": False, "walked": True,
             "heights": [" ".join("-2" if h <= 0.05 else str(round(h * 10)) for h in row) for row in GH],
             "_about": "the Muntanya Pelada as the IGN's 5 m terrain model has it (MDT05), the gate's ground y 0: the vestibule levelled, the stair's cut, the hall's and the square's beds, the porticoes' galleries cut into it; let down to the world's level over the site's last 35 m (60 m behind); where it is down at the gate's level it lies just under the world's ground (the street; across the street, it is let down too)"})

# ---------------------------------------------------------------- the boundary wall along Carrer d'Olot, its medallions
def wall_path(P):
    out = [[x, max(ground(x, z + 3.0) + 2.8, ground(x, z - 3.0) + 1.0), z] for x, z in dense(P, 2.0)]
    ys = ma([p[1] for p in out], 2)
    return [[p[0], r3(y), p[2]] for p, y in zip(out, ys)]
for side, P in (("west", WALL_SW), ("east", WALL_NE)):
    path = wall_path(P)
    add(f"{side} wall", {"type": "sweep", "path": path, "step": 1.0, "profile": [[-0.35, -9.0], [0.35, -9.0], [0.35, 0], [-0.35, 0]],
                         "_about": "the wall round the park along Carrer d'Olot (OSM 1430523773 / 1430523772), of the hill's own stone laid rough, 2-4 m over the street, holding back the gardens where they stand higher"})
    add(f"{side} wall crest", {"type": "sweep", "path": path, "step": 1.0, "round": True,
                               "profile": [[-0.42, 0], [0.42, 0], [0.44, 0.25], [0.3, 0.5], [0, 0.6], [-0.3, 0.5], [-0.44, 0.25]],
                               "_about": "its crest, rolled and dressed in trencadis in bands of white and red"})
med = []
for side, P, n in (("west", WALL_SW, 8), ("east", WALL_NE, 7)):
    pts = resample(wall_path(P), 0.5)
    L = [0.0]
    for k in range(1, len(pts)): L.append(L[-1] + math.hypot(pts[k][0] - pts[k - 1][0], pts[k][2] - pts[k - 1][2]))
    for m in range(n):          # (from the gate outward, 8 m apart: the west wall runs toward the gate, the east one away)
        s = (L[-1] - 3.5 - 8.0 * m) if side == "west" else (3.5 + 8.0 * m)
        k = min(range(len(L)), key=lambda q: abs(L[q] - s)); x, y, z, hd = pts[k]
        rx, rz = -math.cos(hd), math.sin(hd)         # (the right of travel: the street)
        med.append([r3(x + rx * 0.4), r3(y - 1.25), r3(z + rz * 0.36), r3(math.atan2(rx, rz))])
add("medallions", {"type": "loft", "axis": "z", "sides": 20, "at": med,
                   "sections": [{"s": -0.05, "a": 0.7, "b": 0.7}, {"s": 0.06, "a": 0.7, "b": 0.7}, {"s": 0.12, "a": 0.6, "b": 0.6}],
                   "_about": "the 15 medallions on the street face, 1.4 m across, 'Park' and 'Guell' in trencadis (sourced number and size; 8 m apart from the gate, estimated)"})

