# ---------------------------------------------------------------- the Calvary on the Turo de les Tres Creus
# (Gaudi's talaiot: a round mound of rough stone, two flights up its side, three crosses on top -- the tallest, the four-armed
#  one, pointing up and to the four quarters, the two lower ones to north-south and east-west; es.wikipedia: the crosses
#  1.7 m and 1.5 m. The mound's size and the flights' places estimated: its foot inside the ring path 61942870)
cg = [tri_h(GW, CALV[0] + (CALV_R + 0.9) * math.cos(t * math.pi / 12), CALV[1] + (CALV_R + 0.9) * math.sin(t * math.pi / 12)) for t in range(24)]
CALV_Y0, CALV_TOP = r3(min(cg) - 0.5), r3(max(cg) + 3.2)
add("calvary", {"type": "prism", "plan": {"sides": 20, "radius": CALV_R}, "height": r3(CALV_TOP - CALV_Y0), "batter": {"out": 0.8, "power": 1.0},
                "at": [[CALV[0], CALV_Y0, CALV[1], 0]], "walked": True,
                "_about": "the Calvary (El Turo de les Tres Creus, OSM 6286148116, 185 m, the park's top): Gaudi's mound of rough stones like a Balearic talaiot, round, battered"})
def calvary_flight(phi):
    """a flight tangent to the mound, arriving on its top at the angle phi round it (going round anticlockwise as it climbs)"""
    nx, nz = math.cos(phi), math.sin(phi); dx, dz = -nz, nx; yaw = math.atan2(-nx, -nz)
    tx, tz = CALV[0] + (CALV_R - 0.05) * nx, CALV[1] + (CALV_R - 0.05) * nz
    n = 14
    for _ in range(8):
        L = n * 0.3; sx, sz = tx - L * dx, tz - L * dz
        foot = [(sx - e * dx + q * nx, sz - e * dz + q * nz) for e in (0.0, 1.0, 2.0) for q in (0.0, 0.6, 1.2)]
        y0 = max(tri_h(GW, x, z) for x, z in foot) + 0.02
        n = max(4, round((CALV_TOP - y0) / 0.19))
    return (r3(sx), r3(y0), r3(sz), r3(yaw), n, (r3(tx), r3(tz))), [r3(sx - dx * 1.0 + nx * 0.6), r3(y0 - 1.5), r3(sz - dz * 1.0 + nz * 0.6), r3(yaw)]
# (its two flights: on the sides where the ground stands highest, so they are short -- two of 36 places round, about half a turn apart)
cands = sorted((calvary_flight(k * math.pi / 18)[0][4], k) for k in range(36))
k1 = cands[0][1]; k2 = min((c for c in cands if 12 <= (c[1] - k1) % 36 <= 24), key=lambda c: c[0])[1]
fl_at, pad_at = zip(*(calvary_flight(k * math.pi / 18) for k in (k1, k2)))
for k, (x, y, z, yaw, n, _) in enumerate(fl_at):
    add(f"calvary flight {k + 1}", {"type": "flight", "width": 1.2, "run": 0.3, "steps": n, "base": 0, "top": r3(CALV_TOP - y), "landing": 0, "ground": -1.5,
                                    "railing": False, "at": [[x, y, z, yaw]], "_about": "a flight up the mound's side, of the same rough stone, arriving on its top"})
add("calvary foot", {"type": "prism", "plan": {"rect": [2.0, 1.2]}, "height": 1.5, "at": pad_at, "walked": True,
                     "_about": "the flights' feet, levelled on the slope"})
add("calvary cross", {"type": "component", "use": "components/gaudi-cross", "params": {"h": 1.7, "arm": 0.42, "t": 0.15},
                      "at": [[CALV[0], CALV_TOP, CALV[1], r3(math.radians(48.3))]], "_about": "the tallest cross, Gaudi's four-armed one, its arms to the four quarters and its head up"})
lc = [[r3(CALV[0] + 1.25 * c), CALV_TOP, r3(CALV[1] + 1.25 * sn), r3(math.radians(48.3) + q)] for c, sn, q in ((math.cos(2.2), math.sin(2.2), 0.0), (math.cos(-0.9), math.sin(-0.9), math.pi / 2))]
add("calvary crosses", {"type": "box", "width": 0.14, "length": 0.14, "height": 1.5, "at": lc, "_about": "the two lower crosses' uprights (1.5 m)"})
add("calvary cross bars", {"type": "box", "width": 0.75, "length": 0.12, "height": 0.13, "at": [[p[0], r3(p[1] + 1.02), p[2], p[3]] for p in lc],
                           "_about": "their bars, one north-south, one east-west"})

# (the paths keep off the Calvary's flights: where one crosses a flight's foot, it stops short)
def on_flight(x, z, m):
    for fx, fy, fz, yaw, n, (tx, tz) in fl_at:
        nx, nz = -math.sin(yaw), -math.cos(yaw)
        if seg_d(x, z, (fx + nx * 0.6, fz + nz * 0.6), (tx + nx * 0.6, tz + nz * 0.6)) < 0.6 + m: return True
        if math.hypot(x - (fx + nx * 0.6), z - (fz + nz * 0.6)) < 2.4 + m: return True
    return False
cut = []
for r in RUNS:
    cur = []
    for q, y in list(zip(r[3], r[4])) + [(None, None)]:
        if q is not None and not on_flight(q[0], q[1], r[2] / 2 + 0.4): cur.append((q, y)); continue
        if len(cur) >= 3: cut.append([r[0], r[1], r[2], [c[0] for c in cur], [c[1] for c in cur]])
        cur = []
RUNS = cut
# ---------------------------------------------------------------- the paths (OSM's footways), laid on the cut ground
for kind_set, nm, about in (({"footway", "path", "pedestrian", "track"}, "paths", "the park's footways (OSM, every footway, path and track inside Parc Guell's outline that is clear of what is built): earth and gravel on a bank of the hill's rubble, its side a retaining wall where the way runs across the slope"),
                            ({"steps"}, "path steps", "the ways OSM has as steps, laid as the paths are (their treads not cut)")):
    rs = [r for r in RUNS if r[1] in kind_set]
    if not rs: continue
    widths = sorted({r[2] for r in rs})
    for w in widths:
        add(f"{nm} {w:g}m" if len(widths) > 1 else nm,
            {"type": "sweep", "paths": [[[x, y, z] for (x, z), y in zip(r[3], r[4])] for r in rs if r[2] == w], "step": 2.0,
             "profile": [[r3(-w / 2), 0], [r3(w / 2), 0], [r3(w / 2 + 0.25), -2.2], [r3(-w / 2 - 0.25), -2.2]],
             "_about": about + f" ({w:g} m wide)"})

# ---------------------------------------------------------------- the trees: pines, carobs and palms where the imagery shows canopy
def clear_of_built(x, z):
    if z > -1.0: return False
    if near(FLOORP, x, z, 2.5) or near(TERRACE, x, z, 2.0): return False
    if -27 <= x <= 24 and -19 <= z <= 1: return False
    if abs(x - AX) < 11 and -44 < z < -12: return False
    for B in (LODGE_BOX, ADMIN_BOX, COTXERA, LARRARD, MUSEU):
        if near(B, x, z, 2.0): return False
    for nm, P, ys, W in PORTICOES:
        if poly_d(P, x, z, False) < W + 5.0: return False     # (the galleries open to the view, as they are kept)
    for v in VIA.values():
        if poly_d(v["path"], x, z, False) < v["W"] + 5.0: return False
    for P in (WALL_SW, WALL_NE):
        if poly_d(P, x, z, False) < 2.0: return False
    if math.dist((x, z), CALV) < 13.0 or any(seg_d(x, z, (f[0], f[2]), f[5]) < 5.5 for f in fl_at): return False   # (the Calvary stands bare, as it does)
    if near_path(x, z, 2.5): return False                      # (the paths in the open, a clearing along each)
    return GX0 + 6 < x < GX1 - 6 and GZ0 + 6 < z < GZ1 and ground(x, z) > 0.3
def hsh(k, salt): return ((k * 2654435761 + salt * 40503) % 1000003) / 1000003.0
def glade(x, z):
    """the glades: where the woods open (a slow field over the hill; about a fifth of it bare)"""
    return math.sin(x / 23.0 + 1.3) * math.sin(z / 19.0 + 0.4) + 0.6 * math.sin((x + z) / 31.0 + 2.1)
# THE KINDS: Aleppo pines over most of the hill (tall bare trunks, flat open crowns), carobs and holm oaks on the lower
# terraces (short trunks, dense round crowns), Canary palms about the square and the entrance. (crown radius, trunk to
# the crown's foot, the trunk's radius, the crown's depth over its radius)
KINDS = {"pine small": (2.4, 4.2, 0.15, 0.55), "pine": (3.4, 6.5, 0.2, 0.5), "pine tall": (4.4, 9.5, 0.27, 0.45),
         "carob small": (1.9, 1.6, 0.15, 1.2), "carob": (2.8, 2.0, 0.22, 1.1),
         "palm": (2.6, 7.0, 0.3, 0.0), "palm tall": (2.9, 10.5, 0.3, 0.0)}
trunks = {k: [] for k in KINDS}; placed = []
for k, (x, z, r) in enumerate(TREES):
    if not clear_of_built(x, z): continue
    g = glade(x, z)
    if g > 0.95 or (g > 0.7 and hsh(k, 1) < 0.6): continue
    by_square = poly_d(TERRACE, x, z) < 30 or (abs(x - AX) < 60 and z > -55)
    h0 = ground(x, z)
    if by_square and hsh(k, 2) < 0.55: kind = "palm tall" if hsh(k, 3) < 0.4 else "palm"
    elif h0 < 24 and hsh(k, 4) < 0.6 or h0 >= 24 and hsh(k, 4) < 0.15: kind = "carob" if r >= 4 and hsh(k, 5) < 0.6 else "carob small"
    else:
        u = hsh(k, 6) * 0.75 + (r / 6.0) * 0.25
        kind = "pine tall" if u > 0.72 else "pine" if u > 0.42 else "pine small"
    cr, th, tr, dp = KINDS[kind]; y = max(ground(x, z) - 1.2, ground_low(x, z) - 0.1)
    top = cr * max(dp, 0.4)
    # (on the steep slopes a tree's foot can fall in the crown of the one below it: then only the lower one)
    if any(math.hypot(x - qx, z - qz) < max(qr, cr) + 0.5 and (qy + qt - 1.0 < y < qy + qt + qr or y + th - 1.0 < qy < y + th + top) for qx, qz, qy, qr, qt in placed): continue
    placed.append((x, z, y, cr, th))
    trunks[kind].append([x, r3(y), z, r3((k * 2.39996) % (2 * math.pi))])
for kind, (cr, th, tr, dp) in KINDS.items():
    at = trunks[kind]
    if not at: continue
    sp = kind.split()[0]
    if sp == "palm":
        add(f"{kind} trunks", {"type": "column", "radius": tr, "height": r3(th + 1.2), "sides": 6, "taper": 0.85, "at": at,
                               "_about": f"Canary palms' trunks ({len(at)}), ringed with the old fronds' scars"})
        add(f"{kind} fronds", {"type": "loft", "axis": "y", "sides": 16, "at": [[p[0], r3(p[1] + th), p[2], p[3]] for p in at] + [[p[0], r3(p[1] + th), p[2], r3(p[3] + 0.39)] for p in at],
                               "sections": [{"s": -0.9, "a": 0.25, "b": 0.25, "n": 0.6}, {"s": 0.3, "a": r3(cr * 0.7), "b": r3(cr * 0.7), "n": 0.55},
                                            {"s": 0.8, "a": cr, "b": cr, "n": 0.45}, {"s": 1.2, "a": r3(cr * 0.6), "b": r3(cr * 0.6), "n": 0.5}, {"s": 1.5, "a": 0.2, "b": 0.2}],
                               "_about": "their crowns of fronds, arching out and down (two stars of four, one turned on the other)"})
        continue
    add(f"{kind} trunks", {"type": "column", "radius": tr, "height": r3(th + 0.6), "sides": 5, "taper": 0.7, "at": at,
                           "_about": f"the {'Aleppo pines' if sp == 'pine' else 'carobs and holm oaks'}' trunks ({len(at)}, where the World Imagery tiles show canopy)"})
    H_ = cr * dp
    secs = ([{"s": 0, "a": r3(cr * 0.35), "b": r3(cr * 0.3)}, {"s": r3(H_ * 0.35), "a": r3(cr * 0.95), "b": r3(cr * 0.8)}, {"s": r3(H_ * 0.6), "a": cr, "b": r3(cr * 0.85)},
             {"s": r3(H_ * 0.85), "a": r3(cr * 0.7), "b": r3(cr * 0.6)}, {"s": r3(H_), "a": r3(cr * 0.15), "b": r3(cr * 0.12)}] if sp == "pine" else
            [{"s": 0, "a": r3(cr * 0.4), "b": r3(cr * 0.4)}, {"s": r3(H_ * 0.3), "a": r3(cr * 0.92), "b": r3(cr * 0.88)}, {"s": r3(H_ * 0.55), "a": cr, "b": r3(cr * 0.95)},
             {"s": r3(H_ * 0.82), "a": r3(cr * 0.75), "b": r3(cr * 0.7)}, {"s": r3(H_), "a": r3(cr * 0.1), "b": r3(cr * 0.1)}])
    add(f"{kind} crowns", {"type": "loft", "axis": "y", "sides": 7, "at": [[p[0], r3(p[1] + th), p[2], p[3]] for p in at], "sections": secs,
                           "_about": "their crowns, " + ("broad, flat-topped and open, high on the trunk" if sp == "pine" else "dense and round, low")})

# (what carries comes first: the floors before the columns on them, the legs before the dragon)
def before(a, b):
    build.remove(a); build.insert(build.index(b), a)
before("hall floor", "columns")

